  foreach (var tr in Resources.FindObjectsOfTypeAll<Transform>()) {
    if (tr == null || tr.parent != null || !tr.gameObject.scene.IsValid()) continue;
    if (System.Array.IndexOf(probes, tr.name) < 0) continue;
    UnityEngine.Object.DestroyImmediate(tr.gameObject);
    gone++;
  }
  if (gone > 0) log += "probes-destroyed=" + gone + " ";
} catch (System.Exception ex) { log += "probe cleanup failed: " + ex.Message + " "; }
return log.Length == 0 ? "nothing to restore" : log;
